export interface UserAccountProps {
  id: string;
  email: string;
}

export class UserAccount {
  private constructor(private readonly props: UserAccountProps) {}

  public static create(id: string, email: string): UserAccount {
    return new UserAccount({ id, email });
  }

  public updateEmail(newEmail: string): void {
    if (!this.isValidEmail(newEmail)) {
      throw new Error('Invalid email address');
    }

    this.props.email = newEmail;
    // In a real implementation, you'd want to save the updated entity
    // this.save();
  }

  private isValidEmail(email: string): boolean {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  }
}

// Application Layer - Use case
export interface UpdateUserEmailUseCase {
  execute(userId: string, newEmail: string): Promise<void>;
}

export class UpdateUserEmail implements UpdateUserEmailUseCase {
  constructor(private readonly userAccountRepository: UserAccountRepository) {}

  async execute(userId: string, newEmail: string): Promise<void> {
    const existingAccount = await this.userAccountRepository.findById(userId);

    if (!existingAccount) {
      throw new Error('User account not found');
    }

    if (!this.isValidEmail(newEmail)) {
      throw new Error('Invalid email address');
    }

    existingAccount.updateEmail(newEmail);
  }

  private isValidEmail(email: string): boolean {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  }
}

// Infrastructure Layer - Repository interface
export interface UserAccountRepository {
  findById(id: string): Promise<UserAccount | null>;
  save(account: UserAccount): Promise<void>;
}

// Concrete implementation of repository
export class PrismaUserAccountRepository implements UserAccountRepository {
  async findById(id: string): Promise<UserAccount | null> {
    const account = await this.prisma.user.findUnique({
      where: { id }
    });

    return account ? new UserAccount(account) : null;
  }

  async save(account: UserAccount): Promise<void> {
