// Domain Layer - Pure Business Logic
export interface Product {
  id: string;
  name: string;
  price: number;
}

export class ProductEntity {
  constructor(
    public readonly id: string,
    public readonly name: string,
    public readonly price: number
  ) {}

  applyDiscount(percent: number): void {
    if (percent < 0 || percent > 100) {
      throw new Error('Invalid discount percentage');
    }

    this.price = this.price * (1 - percent / 100);
  }
}

// Application Layer - Use Cases
export interface IProductService {
  findById(id: string): Promise<Product | null>;
  save(product: Product): Promise<void>;
  applyDiscount(productId: string, discountPercentage: number): Promise<void>;
}

// Infrastructure Layer - Database Adapter
export class ProductRepository {
  async findById(id: string): Promise<ProductEntity | null> {
    // Implementation to fetch from database
    const productData = await this.repository.findOne(id);

    if (!productData) {
      return null;
    }

    return new ProductEntity(
      productData.id,
      productData.name,
      productData.price
    );
  }

  async save(product: Product): Promise<void> {
    // Implementation to save to database
    await this.repository.save({
      id: product.id,
      name: product.name,
      price: product.price
    });
  }

  async applyDiscount(
    productId: string,
    discountPercentage: number
  ): Promise<void> {
    const product = await this.findById(productId);

    if (!product) {
      throw new Error('Product not found');
    }

    product.applyDiscount(discountPercentage);
    await this.save(product);
  }
}

// Presentation Layer - Web/React
export interface ProductComponentProps {
  productId: string;
  discountPercentage: number;
  onApplyDiscount: () => void;
}
