// Domain Layer - Value Objects and Entities
export class Product {
  constructor(public readonly id: string, public readonly name: string) {}
}

export interface InventoryItem {
  productId: string;
  quantity: number;
}

// Application Layer - Use Cases
export interface IDeductStockUseCase {
  execute(productId: string, quantity: number): Promise<void>;
}

export class DeductStock implements IDeductStockUseCase {
  constructor(
    private readonly inventoryRepository: IInventoryRepository,
    private readonly validator: IInventoryValidator
  ) {}

  async execute(productId: string, quantity: number): Promise<void> {
    // Validate input
    const validation = this.validator.validate(productId, quantity);
    if (validation.isError) {
      throw validation.error;
    }

    // Get current stock
    const item = await this.inventoryRepository.findById(productId);
    if (!item) {
      throw new Error('Product not found');
    }

    // Check inventory availability
    const updatedStock = item.quantity - quantity;
    if (updatedStock < 0) {
      throw new Error('Out of stock');
    }

    // Update inventory
    await this.inventoryRepository.update(productId, updatedStock);
  }
}

// Infrastructure Layer - Repository Interface
export interface IInventoryRepository {
  findById(id: string): Promise<InventoryItem | null>;
  update(productId: string, quantity: number): Promise<void>;
}

// Infrastructure Layer - Validator
export interface IInventoryValidator {
  validate(productId: string, quantity: number): Promise<{ isError: boolean; error?: Error }>;
}

// Infrastructure Layer - Implementation
export class PostgresInventoryRepository implements IInventoryRepository {
  constructor(private readonly client: Client) {}

  async findById(id: string): Promise<InventoryItem | null> {
    const res = await this.client.query(
      'SELECT product_id, quantity FROM inventory WHERE product_id = $1',
      [id]
    );

    if (res.rows.length === 0) {
      return null;
    }

    return {
      productId: res.rows[0].product_id,
      quantity: res.rows[0].quantity
    };
  }

  async update(productId: string, quantity: number): Promise<void> {
    await this.client.connect();
    await this.client.query(
      'UPDATE inventory SET quantity = $1 WHERE product_id = $2',
      [quantity, productId]
    );
  }
}

export class InventoryValidation implements IInventoryValidator {
  validate(productId: string, quantity: number): Promise<{ isError: boolean; error?: Error }> {
    return new Promise((resolve) => {
      if (!productId || typeof productId !== 'string') {
        resolve({ isError: true, error: new Error('Invalid product ID') });
        return;
      }

      if (quantity <= 0 || !Number.isInteger(quantity)) {
        resolve({ isError: true, error: new Error('Invalid quantity') });
        return;
      }

      resolve({ isError: false });
    });
  }
}
