// Domain Layer - Core Business Logic
export interface Subscription {
  id: string;
  userId: string;
  status: 'ACTIVE' | 'EXPIRED' | 'PAUSED';
  expiresAt: Date;
}

export interface SubscriptionRepository {
  findById(id: string): Promise<Subscription | null>;
  save(subscription: Subscription): Promise<void>;
}

// Application Layer - Use Cases
export interface RenewSubscriptionUseCase {
  execute(userId: string): Promise<void>;
}

export class RenewSubscription implements RenewSubscriptionUseCase {
  constructor(
    private readonly subscriptionRepository: SubscriptionRepository
  ) {}

  async execute(userId: string): Promise<void> {
    const existingSubscription = await this.subscriptionRepository.findById(userId);

    if (!existingSubscription) {
      throw new Error('Subscription not found');
    }

    // Business invariants - enforce that only ACTIVE subscriptions can be renewed
    if (existingSubscription.status !== 'ACTIVE') {
      throw new Error('Cannot renew inactive subscription');
    }

    const now = new Date();
    const newExpiresAt = new Date(now.getTime() + 30 * 24 * 3600 * 1000);

    const updatedSubscription: Subscription = {
      ...existingSubscription,
      status: 'ACTIVE',
      expiresAt: newExpiresAt
    };

    await this.subscriptionRepository.save(updatedSubscription);
  }
}

// Infrastructure Layer - Database Implementation
export class MongoSubscriptionRepository implements SubscriptionRepository {
  async findById(id: string): Promise<Subscription | null> {
    const subscription = await SubscriptionModel.findById(id).exec();
    return subscription ? ({ ...subscription.toObject(), id } as Subscription) : null;
  }

  async save(subscription: Subscription): Promise<void> {
    await SubscriptionModel.findByIdAndUpdate(
      subscription._id,
      { ...subscription },
      { new: true }
    ).exec();
  }
}
