// Domain Layer - Core Business Logic
export interface IOrderRepository {
  save(order: Order): Promise<void>;
}

export class Order {
  constructor(
    public readonly id: string,
    public readonly customerId: string,
    public readonly amount: number,
    public readonly createdAt: Date = new Date()
  ) {}
}

// Application Layer - Use Cases
export interface ICreateOrderUseCase {
  execute(customerId: string, amount: number): Promise<void>;
}

export class CreateOrder implements ICreateOrderUseCase {
  constructor(
    private readonly orderRepository: IOrderRepository
  ) {}

  async execute(customerId: string, amount: number): Promise<void> {
    const order = new Order(
      this.generateOrderId(),
      customerId,
      amount
    );

    await this.orderRepository.save(order);
  }

  private generateOrderId(): string {
    // This is a placeholder - in real implementation, you'd use a proper ID generator
    return Math.random().toString(36).substring(2, 9);
  }
}

// Infrastructure Layer - Database Implementation
export class SqliteOrderRepository implements IOrderRepository {
  constructor(private readonly db: sqlite3.Database) {}

  async save(order: Order): Promise<void> {
    await this.db.run(
      'INSERT INTO orders (id, customer_id, amount) VALUES (?, ?, ?)',
      [order.id, order.customerId, order.amount]
    );
  }
}

// Infrastructure Layer - File Persistence Implementation
export class FileOrderRepository implements IOrderRepository {
  constructor(private readonly filePath: string) {}

  async save(order: Order): Promise<void> {
    const db = new sqlite3.Database(this.filePath);
    try {
      await db.run(
        'INSERT INTO orders (id, customer_id, amount) VALUES (?, ?, ?)',
        [order.id, order.customerId, order.amount]
      );
    } finally {
      db.close();
    }
  }
}
