// Domain Layer - Value Objects and Entities
export class PaymentError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'PaymentError';
  }
}

export interface IPaymentToken {
  readonly id: string;
  readonly type: 'credit_card' | 'debit_card';
  readonly number: string;
  readonly expiryDate: Date;
  readonly cvv: string;
}

export interface IAmount {
  readonly amount: number;
  readonly currency: string;
}

// Application Layer - Use Cases
export interface IPaymentService {
  charge(token: IPaymentToken, amount: IAmount): Promise<PaymentResult>;
}

export class PaymentResult {
  constructor(
    public readonly success: boolean,
    public readonly errorMessage?: string
  ) {}
}

// Infrastructure Layer - Adapters
export class PaymentGatewayAdapter implements IPaymentService {
  private readonly apiClient = axios.create({
    baseURL: 'https://api.paymentgateway.com',
    timeout: 1000,
  });

  async charge(token: IPaymentToken, amount: IAmount): Promise<PaymentResult> {
    try {
      const response = await this.apiClient.post('/charges', {
        token: token.id,
        amount: amount.amount,
        currency: amount.currency,
      });

      return {
        success: response.data.success,
        errorMessage: response.data.errorMessage || undefined,
      };
    } catch (error) {
      return {
        success: false,
        errorMessage: `Payment gateway error: ${error instanceof Error ? error.message : 'Unknown error'}`,
      };
    }
  }
}

// Presentation Layer - Controllers or Services
export class PaymentController {
  constructor(private readonly paymentService: IPaymentService) {}

  async handleCharge(req: { token: string; amount: number }): Promise<PaymentResult> {
    try {
      const token = req.token;
      const amount = {
        amount: req.amount,
        currency: 'USD',
      };

      return await this.paymentService.charge(token, amount);
    } catch (error) {
      return {
        success: false,
        errorMessage: `Failed to process payment: ${error instanceof Error ? error.message : 'Unknown error'}`,
      };
    }
  }
}
