// Domain Layer - Value Objects and Entities
export class CountryName {
  private constructor(private readonly value: string) {}

  static create(name: string): CountryName {
    if (!name || name.trim() === '') {
      throw new Error('Country name cannot be empty');
    }

    return new CountryName(name);
  }

  getValue(): string {
    return this.value;
  }
}

// Application Layer - Use Cases
export interface GetCountryByIpUseCase {
  execute(ip: string): Promise<CountryName>;
}

export class GetCountryByIp implements GetCountryByIpUseCase {
  constructor(private readonly geolocationService: GeolocationService) {}

  async execute(ip: string): Promise<CountryName> {
    const response = await this.geolocationService.getCountryByIp(ip);
    return CountryName.create(response);
  }
}

// Infrastructure Layer - Concrete Implementation
export class HttpGeolocationService implements GeolocationService {
  async getCountryByIp(ip: string): Promise<{ country_name: string }> {
    const res = await fetch(`https://ipapi.co/${ip}/json/`);
    const data = await res.json();

    if (!data || !data.country_name) {
      throw new Error('Failed to retrieve country information');
    }

    return data;
  }
}

// Presentation Layer - Express Route
import { GetCountryByIpUseCase } from '../application/ports';

export class CountryController {
  constructor(private readonly getCountryByIp: GetCountryByIpUseCase) {}

  async getCountries(req: Request, res: Response): Promise<void> {
    const ip = req.headers['x-forwarded-for'] || req.connection.remoteAddress;

    try {
      const countryName = await this.getCountryByIp.execute(ip);

      res.json({
        country_name: countryName.getValue()
      });
    } catch (error) {
      res.status(500).json({ error: 'Failed to retrieve country information' });
    }
  }
}
