    const sessionData: SessionData = { userId };
    const session = new Session(sessionId, sessionData);

    await this.sessionRepository.save(session);
  }
}

// Infrastructure Layer - Redis Implementation
export class RedisSessionRepository implements ISessionRepository {
  constructor(private readonly redis: Redis) {}

  async save(session: Session): Promise<void> {
    const sessionId = session.sessionId;
    const userId = session.data.userId;

    await this.redis.set(`session:${sessionId}`, JSON.stringify({ userId }), 'EX', 3600);
  }

  async findById(id: string): Promise<Session | null> {
    try {
      const rawValue = await this.redis.get(`session:${id}`);
      if (!rawValue) return null;

      const data = JSON.parse(rawValue) as SessionData;
      return new Session(id, data);
    } catch {
      return null;
    }
  }
}
```

