// Domain Layer - Pure Business Logic
export interface IBankAccountRepository {
  findById(id: string): Promise<BankAccount | null>;
  save(account: BankAccount): Promise<void>;
}

export class BankAccount {
  private constructor(public readonly id: string, public balance: number) {}

  static create(): BankAccount {
    return new BankAccount(generateId(), 0);
  }

  deposit(amount: number): void {
    if (amount <= 0) {
      throw new Error("Deposit amount must be positive");
    }

    this.balance += amount;
  }

  withdraw(amount: number): void {
    if (amount <= 0 || amount > this.balance) {
      throw new Error("Insufficient funds for withdrawal");
    }

    this.balance -= amount;
  }

  get balance(): number {
    return this.balance;
  }

  static fromRepository(accountId: string, repository: IBankAccountRepository): Promise<BankAccount> {
    return repository.findById(accountId)
      .then(foundAccount => {
        if (!foundAccount) {
          throw new Error("Account not found");
        }

        return new BankAccount(accountId, foundAccount.balance);
      });
  }

  static save(account: BankAccount): Promise<void> {
    return repository.save({
      id: account.id,
      balance: account.balance
    });
  }
}

// Application Layer - Use Cases
export interface IDepositUseCase {
  execute(accountId: string, amount: number): Promise<void>;
}

export class DepositUseCase implements IDepositUseCase {
  constructor(private readonly repository: IBankAccountRepository) {}

  async execute(accountId: string, amount: number): Promise<void> {
    const account = await BankAccount.fromRepository(accountId, this.repository);

    if (amount <= 0) {
      throw new Error("Deposit amount must be positive");
    }

    account.deposit(amount);
    await BankAccount.save(account);
  }
}

// Infrastructure Layer - Database Implementation
export class BankAccountEntity {
  constructor(
    public readonly id: string,
    public balance: number
  ) {}

  static create(id: string, balance: number): BankAccountEntity {
    return new BankAccountEntity(id, balance);
  }

  static fromRepository(entity: { id: string; balance: number }): BankAccountEntity {
    return new BankAccountEntity(entity.id, entity.balance);
  }
}

export class BankAccountRepository implements IBankAccountRepository {
  async findById(id: string): Promise<BankAccount | null> {
    // Database query implementation
    const entity = await this.repository.findById(id);

    if (!entity) {
      return null;
    }

    return BankAccountEntity.fromRepository(entity);
  }

  async save(account: BankAccount): Promise<void> {
    // Database update implementation
    await this.repository.save({
      id: account.id,
      balance: account.balance
    });
  }
}
