    public readonly refId: string,
    public readonly charged: number
  ) {}
}

// Application Layer - Use Cases
export class ProcessPaymentUseCase implements IPaymentService {
  constructor(private readonly paymentRepository: PaymentRepository) {}

  async processPayment(payload: PaymentPayload): Promise<IPaymentResult> {
    // Validate input
    const validation = this.validatePayment(payload);
    if (validation.isError) {
      return new PaymentResult(validation.error, '', 0);
    }

    // Process payment (this would be implemented with actual payment service)
    const result = await this.paymentRepository.processPayment(payload);

    return new PaymentResult('SUCCESS', result.refId, result.amount);
  }

  private validatePayment(payload: PaymentPayload): { isError: true; error: string } | { isError: false } {
    if (!payload.id || typeof payload.id !== 'string') {
      return { isError: true, error: 'Invalid payment ID' };
    }

    if (payload.amount <= 0) {
      return { isError: true, error: 'Amount must be greater than zero' };
    }

    return { isError: false };
  }
}

// Infrastructure Layer - Payment Repository
