// Domain Layer - Pure Business Logic
export interface Item {
  price: number;
  qty: number;
}

export interface TotalCalculator {
  calculate(items: Item[]): number;
}

// Application Layer - Use Cases
export class ComputeTotalUseCase implements TotalCalculator {
  constructor(private readonly itemRepository: ItemRepository) {}

  async calculate(items: Item[]): Promise<number> {
    // Validate input (this would be part of the domain)
    const validatedItems = await this.itemRepository.validateItems(items);

    return this.calculateValidated(validatedItems);
  }

  private async calculateValidated(items: Item[]): Promise<number> {
    return items.reduce((acc: number, item: Item) => acc + (item.price * item.qty), 0);
  }
}

// Infrastructure Layer - Data Access
export interface ItemRepository {
  validateItems(items: Item[]): Promise<Item[]>;
}

export class InMemoryItemRepository implements ItemRepository {
  private readonly items: Item[] = [];

  async validateItems(items: Item[]): Promise<Item[]> {
    // Business logic validation here
    const validatedItems = items.filter(item => item.price > 0 && item.qty >= 0);

    return validatedItems;
  }

  addItem(item: Item): void {
    this.items.push(item);
  }

  getItems(): Item[] {
    return [...this.items];
  }
}

// Usage example
const itemRepository = new InMemoryItemRepository();
itemRepository.addItem({ price: 10, qty: 2 });
itemRepository.addItem({ price: -5, qty: 3 }); // Invalid item

const calculator = new ComputeTotalUseCase(itemRepository);
const total = await calculator.calculate(itemRepository.getItems());
console.log(total); // Output will be 20 (10*2 + 0*0)
