export class CheckoutUseCaseImpl implements CheckoutUseCase {
  constructor(
    private readonly paymentGateway: StripePaymentGateway,
    private readonly orderRepository: PostgresOrderRepository
  ) {}

  async execute(
    userId: string,
    cartItems: OrderItem[],
    cardToken: string
  ): Promise<Order> {
    const total = cartItems.reduce((sum, item) => 
      sum + (item.price.amount * item.quantity), 0);

    const chargeResponse = await this.paymentGateway.charge(cardToken, total);

    const orderItems = cartItems.map(item => ({
      productId: item.productId,
      price: item.price,
      quantity: item.quantity
    }));

    const order: Order = {
      id: crypto.randomUUID(),
      userId,
      total: new Money(total, 'usd'),
      items: orderItems
    };

    await this.orderRepository.save(order);

    return order;
  }
}

